with valid as (select id, store_id, product_id, sale_date, units, revenue, add_months(sale_date, 3) as sale_date_plus_months from store_sales where store_id = 2) select date_trunc('year', sale_date_plus_months) as year_start, date_trunc('week', sale_date_plus_months) as week_start, approx_percentile(units, array(0.25, 0.5, 0.75)) as units_quartiles, percentile_approx(revenue, 0.5) as revenue_p50, stddev_samp(revenue) as revenue_stddev, rank() over (partition by date_trunc('year', sale_date_plus_months) order by percentile_approx(revenue, 0.5) desc) as revenue_p50_rank from valid group by date_trunc('year', sale_date_plus_months), date_trunc('week', sale_date_plus_months) order by year_start desc nulls first;
